// Persistence contract and the in-memory implementation (used when SUPABASE_URL is unset, and by tests).
//
// Every write is IDEMPOTENT: the room layer retries failed writes, so replaying the same write must not create a
// duplicate row or fail. Game ids are generated by the server (UUID), so createGame never needs a round trip to learn
// the id.
import type { GameConfig } from './adapter';

export interface StoredCommand {
  seq: number; // 1-based position in the game's command log
  who: number; // seat / player index
  pendingId: number;
  pick: string[];
}

export interface NewGameRecord {
  id: string; // server-generated UUID
  roomCode: string;
  roomName: string;
  config: GameConfig;
}

export interface NewPlayerRecord {
  seat: number;
  guestId: string;
  name: string;
  isHost: boolean;
  tokenHash: string; // sha256 hex of the seat token; the raw token is never stored
}

export interface FinishPatch {
  status: 'won' | 'lost' | 'abandoned';
  endReason: string | null;
  round: number | null;
  commandCount: number;
}

export interface PersistedGame {
  id: string;
  roomCode: string;
  roomName: string;
  config: GameConfig;
  players: NewPlayerRecord[];
  commands: StoredCommand[];
  snapshot: { seq: number; payload: string } | null;
}

/** All writes are idempotent (safe to repeat). The server is the only writer (service role or in-process). */
export interface GameStore {
  readonly kind: 'memory' | 'supabase';
  /** Creates the game row. A repeated call with the same id is a no-op. */
  createGame(rec: NewGameRecord): Promise<void>;
  /** Inserts seats. Seats already present are left unchanged. */
  addPlayers(gameId: string, players: NewPlayerRecord[]): Promise<void>;
  /** Appends a command. Re-appending an identical seq is a no-op; a gap in the log is an error. */
  appendCommand(gameId: string, cmd: StoredCommand): Promise<void>;
  /** Stores (or overwrites) the snapshot taken after `seq` commands. */
  saveSnapshot(gameId: string, seq: number, payload: string): Promise<void>;
  /** Marks the game won, lost or abandoned. */
  finishGame(gameId: string, patch: FinishPatch): Promise<void>;
  /** Games still in progress (status 'playing'), with their players, command log and latest snapshot. */
  loadActiveGames(): Promise<PersistedGame[]>;
}

interface MemRow {
  id: string;
  roomCode: string;
  roomName: string;
  config: GameConfig;
  status: FinishPatch['status'] | 'playing';
  players: NewPlayerRecord[];
  commands: StoredCommand[];
  snapshots: Map<number, string>;
  round: number | null;
  endReason: string | null;
}

export class MemoryStore implements GameStore {
  readonly kind = 'memory' as const;
  private rows = new Map<string, MemRow>();

  async createGame(rec: NewGameRecord): Promise<void> {
    if (this.rows.has(rec.id)) return;
    this.rows.set(rec.id, {
      id: rec.id,
      roomCode: rec.roomCode,
      roomName: rec.roomName,
      config: structuredClone(rec.config),
      status: 'playing',
      players: [],
      commands: [],
      snapshots: new Map(),
      round: null,
      endReason: null,
    });
  }

  private row(id: string): MemRow {
    const r = this.rows.get(id);
    if (!r) throw new Error('unknown game ' + id);
    return r;
  }

  async addPlayers(gameId: string, players: NewPlayerRecord[]): Promise<void> {
    const r = this.row(gameId);
    for (const p of players) {
      if (!r.players.some((existing) => existing.seat === p.seat)) r.players.push({ ...p });
    }
  }

  async appendCommand(gameId: string, cmd: StoredCommand): Promise<void> {
    const r = this.row(gameId);
    const existing = r.commands[cmd.seq - 1];
    if (existing) {
      if (existing.pendingId !== cmd.pendingId || existing.who !== cmd.who) throw new Error(`command ${cmd.seq} already stored with other data`);
      return;
    }
    if (cmd.seq !== r.commands.length + 1) throw new Error(`command seq gap: ${cmd.seq}`);
    r.commands.push({ ...cmd, pick: cmd.pick.slice() });
  }

  async saveSnapshot(gameId: string, seq: number, payload: string): Promise<void> {
    this.row(gameId).snapshots.set(seq, payload);
  }

  async finishGame(gameId: string, patch: FinishPatch): Promise<void> {
    const r = this.row(gameId);
    r.status = patch.status;
    r.endReason = patch.endReason;
    r.round = patch.round;
  }

  async loadActiveGames(): Promise<PersistedGame[]> {
    const out: PersistedGame[] = [];
    for (const r of this.rows.values()) {
      if (r.status !== 'playing') continue;
      let snapshot: PersistedGame['snapshot'] = null;
      for (const [seq, payload] of r.snapshots) if (!snapshot || seq > snapshot.seq) snapshot = { seq, payload };
      out.push({
        id: r.id,
        roomCode: r.roomCode,
        roomName: r.roomName,
        config: structuredClone(r.config),
        players: r.players.map((p) => ({ ...p })),
        commands: r.commands.map((c) => ({ ...c, pick: c.pick.slice() })),
        snapshot,
      });
    }
    return out;
  }
}
